using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AstreaSecondPhaseAnimationData", menuName = "Data/Animation/AstreaSecondPhaseAnimationData")]
public class AstreaSecondPhaseAnimationData : CustomAnimationData
{
	[SerializeField]
	private SingularityGoddessEffect singularityGoddessEffect;

	[Header("VFX")]
	[SerializeField]
	private GameObject solsticeAstreaActivationVFX;

	[SerializeField]
	private GameObject equinoxAstreaActivationVFX;

	[SerializeField]
	private GameObject solsticeAstreaOverCorruptionVFX;

	[SerializeField]
	private GameObject equinoxAstreaOverCorruptionVFX;

	public override AnimationType GetCustomAttackAnimationType(SpriteControl spriteControl, EnemySFXData enemySFXData)
	{
		if ((bool)enemySFXData)
		{
			if (enemySFXData.EnableEnemyAttackDelay)
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, enemySFXData.EnemyAttackDelay, delegate
				{
					enemySFXData.PlayEnemyAttackSFX();
				});
			}
			else
			{
				enemySFXData.PlayEnemyAttackSFX();
			}
		}
		if (singularityGoddessEffect.StateOne)
		{
			SpawnVFX(solsticeAstreaActivationVFX, spriteControl.transform.position);
			return AnimationType.Attack;
		}
		SpawnVFX(equinoxAstreaActivationVFX, spriteControl.transform.position);
		return AnimationType.Attack1;
	}

	private void SpawnVFX(GameObject vfxPrefab, Vector3 position)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
		{
			SpawnVFX();
		}
		void SpawnVFX()
		{
			ReferenceSingleton<VFXHandler>.Instance.GetVFX(vfxPrefab, position, 5f);
		}
	}

	public override AnimationType GetCustomOvercorruptAnimationType(SpriteControl spriteControl, EnemySFXData enemySFXData)
	{
		if (singularityGoddessEffect.StateOne)
		{
			SpawnVFX(solsticeAstreaOverCorruptionVFX, spriteControl.transform.position);
			return AnimationType.Attack2;
		}
		SpawnVFX(equinoxAstreaOverCorruptionVFX, spriteControl.transform.position);
		return AnimationType.Attack3;
	}
}
